// Test-only original FeedbackAdapter/OnSent + actual RTCP wire unmarshal driver.
package cc
import("bufio";"encoding/hex";"encoding/json";"os";"testing";"time";"github.com/pion/interceptor";"github.com/pion/rtcp";"github.com/pion/rtp")
func TestFeedbackSourceOracle(t *testing.T){in,err:=os.Open(os.Getenv("PION_ADAPTER_INPUT"));if err!=nil{t.Fatal(err)};defer in.Close();out,err:=os.Create(os.Getenv("PION_ADAPTER_OUTPUT"));if err!=nil{t.Fatal(err)};defer out.Close();enc:=json.NewEncoder(out);scan:=bufio.NewScanner(in);scan.Buffer(make([]byte,4096),4*1024*1024);for scan.Scan(){var c struct{Name string `json:"name"`;Sent []struct{Seq uint16 `json:"seq"`;SSRC uint32 `json:"ssrc"`;Size int `json:"payload_size"`;AtNS int64 `json:"at_ns"`};Reports []string `json:"reports_hex"`};if err:=json.Unmarshal(scan.Bytes(),&c);err!=nil{t.Fatal(err)};adapter:=NewFeedbackAdapter();sentMetadata:=[]map[string]any{};for _,sent:=range c.Sent{h:=&rtp.Header{Version:2,SequenceNumber:sent.Seq,SSRC:sent.SSRC};ext:=rtp.TransportCCExtension{TransportSequence:sent.Seq};raw,err:=ext.Marshal();if err!=nil{t.Fatal(err)};if err=h.SetExtension(3,raw);err!=nil{t.Fatal(err)};a:=interceptor.Attributes{};a.Set(TwccExtensionAttributesKey,uint8(3));if err=adapter.OnSent(time.Unix(1000,sent.AtNS),h,sent.Size,a);err!=nil{t.Fatal(err)};sentMetadata=append(sentMetadata,map[string]any{"seq":sent.Seq,"ssrc":0,"size":h.MarshalSize()+sent.Size,"departure_ns":sent.AtNS})};for index,wire:=range c.Reports{raw,err:=hex.DecodeString(wire);if err!=nil{t.Fatal(err)};var report rtcp.TransportLayerCC;row:=map[string]any{"case":c.Name,"index":index,"actual_sent":sentMetadata};if err=report.Unmarshal(raw);err!=nil{row["wire_error"]=err.Error()}else{chunks:=[]map[string]any{};for _,v:=range report.PacketChunks{switch v:=v.(type){case *rtcp.RunLengthChunk:chunks=append(chunks,map[string]any{"kind":"run","symbol":v.PacketStatusSymbol,"length":v.RunLength});case *rtcp.StatusVectorChunk:chunks=append(chunks,map[string]any{"kind":"vector","symbols":v.SymbolList})}};delta:=[]int64{};for _,v:=range report.RecvDeltas{delta=append(delta,v.Delta)};row["base"]=report.BaseSequenceNumber;row["reference"]=report.ReferenceTime;row["chunks"]=chunks;row["deltas_us"]=delta;acks,err:=adapter.OnTransportCCFeedback(time.Unix(1001,0),&report);if err!=nil{row["adapter_error"]=err.Error()}else{values:=[]map[string]any{};for _,a:=range acks{v:=map[string]any{"seq":a.SequenceNumber,"ssrc":a.SSRC,"size":a.Size,"departure_ns":nil,"arrival_ns":nil};if !a.Departure.IsZero(){v["departure_ns"]=a.Departure.Sub(time.Unix(1000,0)).Nanoseconds()};if !a.Arrival.IsZero(){v["arrival_ns"]=a.Arrival.Sub(time.Time{}).Nanoseconds()};values=append(values,v)};row["acks"]=values}};if err:=enc.Encode(row);err!=nil{t.Fatal(err)}}};if err:=scan.Err();err!=nil{t.Fatal(err)}}
